class Solution {
public:
    int countAsterisks(std::string s) {
        bool inside = false;
        int ans = 0;
        for (char c : s) {
            if (c == '|') inside = !inside;
            else if (!inside && c == '*') ans++;
        }
        return ans;
    }
};

class Solution {
    public int countAsterisks(String s) {
        boolean inside = false;
        int ans = 0;
        for (char c : s.toCharArray()) {
            if (c == '|') inside = !inside;
            else if (!inside && c == '*') ans++;
        }
        return ans;
    }
}

var countAsterisks = function(s) {
    let inside = false;
    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '|') inside = !inside;
        else if (!inside && s[i] === '*') ans++;
    }
    return ans;
};
